private void ExportToHTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    string strFileName = "SubjectMarkDetail.htm";
    string strHead = HeaderToHTML();
    string strBody = BodyToHTML();
    string str = "<table border='1' cellpadding='4' cellspacing='0' style='border-collapse:collapse; font-family:Times New Roman; font-size:12pt;'>" + strHead + strBody + "</table>";
    str += "<br/>" + StatisticToHTML();

    string strTitle = "<table style='font-family:Times New Roman; font-size:12pt;'><tr><td colspan='2' style='font-weight:bold; text-align:center;'>BẢNG TỔNG KẾT ĐIỂM TOÀN KHÓA";
    if (uYearSemester.SemesterEditValue != null)
        strTitle += " _ HỌC KÌ " + uYearSemester.SemesterEditValue.ToString();
    strTitle += " _ NIÊN HỌC " + uYearSemester.YearEditValueText;
    strTitle += "</td></tr>";
    strTitle += "<tr><td>KHOÁ HỌC: " + uClass.CourseName + "</td><td>BẬC: " + uClass.TrainingLevelName + "</td></tr>";
    if (uClass.RegulationID == 25)
        strTitle += "<tr><td>NGÀNH: " + uClass.BranchName + "</td><td>LỚP: " + uClass.ClassName + "</td></tr></table>";
    else
        strTitle += "<tr><td>NGHỀ: " + uClass.BranchName + "</td><td>LỚP: " + uClass.ClassName + "</td></tr></table>";

    string strFileContent = GetHTMLTemplate(strFileName);
    strFileContent = strFileContent.Replace("{TITLE}", strTitle);
    strFileContent = strFileContent.Replace("{DETAIL}", str);
    strFileContent = strFileContent.Replace("{HEADER}", strReport_Header);
    strFileContent = strFileContent.Replace("{PLACE}", strReport_Place);

    string strFileNameAs = uClass.ClassIDEditValue + "_" + strFileName;
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

private string GetHTMLTemplate(string strFileName)
{
    try
    {
        return Libs.Files.ReadFile(strFileName);
    }
    catch
    {
        return "<!DOCTYPE html><html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8'/><title>Bảng điểm toàn khóa</title></head><body>{HEADER}<br/>{PLACE}<br/>{TITLE}<br/>{DETAIL}</body></html>";
    }
}

private string FormatMarkValueForHTML(object objValue)
{
    if (objValue == null || objValue == DBNull.Value || objValue.ToString().Trim() == "")
        return "&nbsp;";

    string strValue = objValue.ToString().Trim();
    if (strValue == "-1" || strValue == "-1.0" || strValue == "-1,0")
        return "R";
    if (strValue == "-2" || strValue == "-2.0" || strValue == "-2,0")
        return "P";
    return strValue;
}

private bool IsFailedModuleMark(object objValue)
{
    string strValue = FormatMarkValueForHTML(objValue);
    if (strValue == "&nbsp;" || strValue == "P" || strValue == "R")
        return false;

    double dblMark = 0;
    if (!double.TryParse(strValue, out dblMark))
        return false;
    return dblMark < 5;
}

private string HeaderToHTML()
{
    int intSubjectCount = dtbClassSubject.Rows.Count;
    string strStyle = " style='background-color:#cccccc; font-weight:bold; text-align:center;' ";

    string strRow1 = "<tr" + strStyle + ">";
    strRow1 += "<td rowspan='3'>Số TT</td>";
    strRow1 += "<td rowspan='3'>Họ và tên học sinh</td>";
    strRow1 += "<td colspan='" + intSubjectCount.ToString() + "'>Kết quả học tập mô-đun</td>";
    strRow1 += "<td rowspan='3'>Mô-đun phải học lại</td>";
    strRow1 += "</tr>\r\n";

    string strRow2 = "<tr" + strStyle + ">";
    foreach (DataRow drwSubject in dtbClassSubject.Rows)
    {
        strRow2 += "<td>Tên MĐ: " + drwSubject["SubjectName"].ToString()
            + "<br/>Hệ số: " + drwSubject["UnitText"].ToString() + "</td>";
    }
    strRow2 += "</tr>\r\n";

    string strRow3 = "<tr" + strStyle + ">";
    for (int i = 0; i < intSubjectCount; i++)
        strRow3 += "<td>Điểm mô-đun</td>";
    strRow3 += "</tr>\r\n";

    return strRow1 + strRow2 + strRow3;
}

private string BodyToHTML()
{
    StringBuilder sb = new StringBuilder();
    int intSTT = 0;

    for (int i = 0; i < gvData.RowCount; i++)
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td style='text-align:center;'>" + intSTT.ToString() + "</td>");

        string strFullName = (drw["StudentFirstName"].ToString() + " " + drw["StudentLastName"].ToString()).Trim();
        sb.Append("<td style='text-align:left;'>" + strFullName + "</td>");

        StringBuilder sbRetake = new StringBuilder();
        for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
        {
            int intIndex = j + 1;
            string strField = "FinalSummary_" + intIndex.ToString();
            object objValue = drw[strField];
            string strValue = FormatMarkValueForHTML(objValue);
            string strStyle = " style='text-align:center;' ";

            if (IsFailedModuleMark(objValue))
            {
                strStyle = " style='background-color:Yellow; text-align:center;' ";
                if (sbRetake.Length > 0)
                    sbRetake.Append(", ");
                sbRetake.Append(dtbClassSubject.Rows[j]["SubjectName"].ToString());
            }

            sb.Append("<td" + strStyle + ">" + strValue + "</td>");
        }

        string strRetake = sbRetake.Length > 0 ? sbRetake.ToString() : "&nbsp;";
        sb.Append("<td style='text-align:left;'>" + strRetake + "</td>");
        sb.Append("</tr>\r\n");
    }

    return sb.ToString();
}

private string StatisticToHTML()
{
    double dblCount = gvData.RowCount;
    string[] strCaption = { "Xuất sắc", "Giỏi", "Khá", "TB khá", "Trung bình", "Yếu kém" };
    string strRow = "<table><tr>";
    for (int i = 0; i < 6; i++)
    {
        strRow += "<td style='background-color:#cccccc;'>" + strCaption[i] + "</td><td>"
           + arrStatisticCount[i].ToString() + " (" + Math.Round(arrStatisticCount[i] / dblCount * 100,0).ToString() + "%)</td>";
    }
    strRow += "</tr></table>";

    return strRow;
}

